(window.BOOKS ||= []).push({"id":"algoritmos","title":"Algoritmos","subtitle":"Estructuras de datos y patrones","cover":["#8de6bf","#6aa8ff"],"chapters":[{"title":"Fundamentos y complejidad","concepts":[{"title":"Algoritmo y estructura de datos (DSA)","que":[{"t":"p","x":"Un algoritmo es un conjunto de instrucciones bien definidas que, dadas unas entradas, producen la salida deseada (entradas/salidas precisas, pasos claros, eficiente, independiente del lenguaje). Una estructura de datos guarda y manipula datos mientras se ejecuta un algoritmo. DSA es la base de la resolución de problemas; Python es buen lenguaje para aprenderlo por su sintaxis simple y tipado dinámico."}],"ejemplo":[],"qa":[{"q":"¿Qué es una estructura de datos y qué cualidades tiene un buen algoritmo?","a":"Estructura de datos: forma de guardar y manipular datos mientras corre un algoritmo. Buen algoritmo: entradas/salidas precisas, pasos claros, eficiencia y sin depender de un lenguaje."}]},{"title":"Estructuras de control","que":[{"t":"p","x":"Deciden el orden de ejecución: secuencia (por defecto), selección (`if/elif/else`) e iteración (`for` cuando sabes qué recorres; `while` mientras se cumpla una condición)."}],"ejemplo":[],"qa":[{"q":"¿Cuáles son las tres familias de estructuras de control?","a":"Secuencia, selección e iteración."}]},{"title":"Pseudocódigo verificable (ejemplo: compresión RLE)","que":[{"t":"p","x":"Escribir la lógica en lenguaje humano antes del código; es bueno si se puede simular a mano con un ejemplo concreto y da el resultado esperado. Ejemplo RLE (`AABCCCDEEEE` -> `2AB3CD4E`): recorrer con `enumerate`, mantener `cuenta`, `resultado` y `caracter_guardado`; si el actual es igual suma 1; si cambia, añade `cuenta+car` (o solo el car si cuenta=1), reinicia `cuenta=1` y actualiza el guardado; el último grupo se cierra al llegar al índice `len-1`."}],"ejemplo":[{"t":"p","x":"`\"AABCCCDEEEE\" -> \"2AB3CD4E\"`"}],"qa":[{"q":"¿Cuándo es bueno un pseudocódigo y, en RLE, por qué `cuenta` se reinicia a 1 y no a 0?","a":"Es bueno si es verificable (se recorre a mano con un caso concreto). Se reinicia a 1 porque el carácter nuevo que provocó el cambio ya cuenta como una aparición."}]},{"title":"Casos borde que probar siempre","que":[{"t":"p","x":"Lista vacía, un elemento, duplicados, negativos, entradas muy grandes, tipos inválidos, nulos, límites exactos (18 años, 0). Se anotan en papel antes de programar junto con entrada, salida y complejidad."}],"ejemplo":[],"qa":[{"q":"¿Qué casos borde pruebas en una función que procesa una lista?","a":"Vacía, un elemento, duplicados, negativos, valores extremos y tipos inválidos."}]},{"title":"Notación Big O","que":[{"t":"p","x":"Lenguaje matemático que describe cómo crece el trabajo (tiempo o memoria adicional) de un algoritmo al crecer `n`, sin depender de la máquina ni del lenguaje. Escalas: O(1) constante (`arr[0]`, buscar en dict/set), O(log n) logarítmica (búsqueda binaria; cada paso descarta la mitad), O(n) lineal (un `for`; buscar en una lista), O(n log n) casi lineal (merge sort, quicksort promedio, ordenar), O(n²) cuadrática (bucles anidados, bubble sort), O(2ⁿ) exponencial (subconjuntos, fibonacci recursivo sin memo), O(n!) factorial (permutaciones, viajante por fuerza bruta). Exponencial y factorial son intratables desde n≈20-30. Se distingue tiempo de espacio y se entiende, no se memoriza."}],"ejemplo":[],"qa":[{"q":"¿Qué significa O(log n), qué ejemplo hay y qué orden tiene un loop dentro de otro sobre los mismos datos?","a":"O(log n): cada paso descarta la mitad (búsqueda binaria en array ordenado). Loop dentro de loop: O(n²). Buscar: lista O(n), set/dict O(1) promedio."}]},{"title":"Big O: para comparar, no es una promesa","que":[{"t":"p","x":"La notación suele citar el peor caso, pero la realidad difiere. El dict es O(1) promedio y degenera a O(n) con colisiones (miente \"para mejor\"). `sorted()` es O(n log n) peor caso pero Timsort llega a O(n) con datos ya ordenados (miente \"para peor\")."}],"ejemplo":[],"qa":[{"q":"¿Por qué el dict es O(1) \"promedio\" y no garantizado?","a":"Porque si todas las claves colisionan en el mismo bucket, buscar recorre todo: O(n)."}]},{"title":"Bucles consecutivos y anidados","que":[{"t":"p","x":"Bucles consecutivos suman costes (O(n + m)); anidados los multiplican (O(n·m)); los límites constantes no cambian el orden; si los tamaños son independientes, se mantienen separados."}],"ejemplo":[],"qa":[{"q":"¿Cuál es el coste de dos bucles anidados de tamaños n y m?","a":"O(n·m)."}]},{"title":"Medir rendimiento con time.perf_counter","que":[{"t":"p","x":"Para comparar O(n) vs O(n²) se cronometran ambas con listas de 1.000, 5.000 y 10.000 elementos usando `time.perf_counter()`."}],"ejemplo":[],"qa":[{"q":"¿Qué función usas para medir tiempos con alta resolución?","a":"`time.perf_counter()`."}]}]},{"title":"Estructuras de datos","concepts":[{"title":"Pointer","que":[{"t":"p","x":"Variable que guarda la dirección de memoria de otro valor: el \"mapa del tesoro\" hacia el dato. En el vault aparece en el campo `next` de un Node."}],"ejemplo":[],"qa":[{"q":"¿Qué es un pointer?","a":"Una variable que almacena la dirección de memoria de otro valor."}]},{"title":"Node (nodo)","que":[{"t":"p","x":"Bloque básico de una linked list con `data` y un pointer `next`; no requiere memoria contigua. `head` es el primero; `tail`/último apunta a `null`. También forma los BST (con dos punteros: izquierda y derecha) y el Trie."}],"ejemplo":[],"qa":[{"q":"¿Cuáles son las dos partes de un node?","a":"Data (el valor) y next pointer (referencia al siguiente)."}]},{"title":"Linked List","que":[{"t":"p","x":"Colección ordenada donde cada elemento (Node) guarda un dato (`data`) y una referencia al siguiente (`next`). El primero es el `head`; el último apunta a `None`. A diferencia de la lista (bloque contiguo), las referencias van en los propios elementos; recorrerla es lineal y no hay acceso aleatorio. Usos: navegador (atrás/adelante), playlist; base de stacks, queues y graphs."}],"ejemplo":[],"qa":[{"q":"¿Qué es el head y qué debe apuntar el next del último nodo?","a":"El head es el primer nodo; el `next` del último apunta a `None`."}]},{"title":"Stack (LIFO)","que":[{"t":"p","x":"Estructura de acceso por un solo extremo (top): el último en entrar es el primero en salir. En Python es una lista con `.append()`/`.pop()`. Es la base del call stack, del parseo de texto anidado (Markdown), de DFS y de `RecursionError`."}],"ejemplo":[],"qa":[{"q":"¿Qué regla sigue un stack?","a":"LIFO: el último en entrar es el primero en salir."}]},{"title":"Call stack y RecursionError","que":[{"t":"p","x":"Pila que Python usa para recordar a dónde volver tras cada llamada a función. Un traceback es el call stack mostrado de arriba abajo, con la función que falló al final. Se llena con una recursión sin caso base (o demasiado profunda) y da `RecursionError`."}],"ejemplo":[],"qa":[{"q":"¿Qué es un traceback en términos de stacks y qué es un `RecursionError`?","a":"El traceback es el call stack en orden de llamadas, terminando donde falló. `RecursionError`: el call stack se llenó."}]},{"title":"Pila (stack) y paréntesis balanceados","que":[{"t":"p","x":"Pila LIFO: apilas al abrir; al cerrar, desapilas y comparas con el par esperado; al final debe quedar vacía. Cuidado con cerrar con la pila vacía."}],"ejemplo":[{"t":"p","x":"`pares = {\")\":\"(\",\"]\":\"[\",\"}\":\"{\"}`"}],"qa":[{"q":"¿Diferencia entre pila y cola?","a":"Pila = LIFO (último en entrar, primero en salir); cola = FIFO (primero en entrar, primero en salir)."}]},{"title":"Queue (FIFO) y deque","que":[{"t":"p","x":"Cola con acceso por ambos extremos: el primero en entrar es el primero en salir. Una lista normal es ineficiente (sacar del inicio es O(n)); usar `collections.deque` (O(1))."}],"ejemplo":[],"qa":[{"q":"¿Por qué usar `deque` y no una lista para una cola?","a":"Porque sacar del inicio de una lista es O(n); en deque es O(1)."}]},{"title":"Hash (función hash)","que":[{"t":"p","x":"Operación matemática irreversible que da una huella de longitud fija; cambiar un bit cambia todo el hash. Convierte una clave en un número que decide dónde se guarda el valor (lookup rápido). No se revierte por pérdida de información, función unidireccional y colisiones infinitas; solo por fuerza bruta (SHA-256 tardaría miles de años). En Python, `hash(key)` decide el bucket."}],"ejemplo":[],"qa":[{"q":"¿Por qué no se puede revertir un hash?","a":"Hay pérdida de información, es unidireccional y infinitas entradas dan la misma salida."}]},{"title":"HashMap, Hash Table y dict","que":[{"t":"p","x":"HashMap, HashTable, Map, Dictionary o Associative son nombres de la misma estructura clave-valor. Una función hash convierte la clave en un número que determina dónde guardar el valor, saltando directo en vez de escanear. La hash table es la base conceptual; el HashMap la estructura abstracta; el dict su implementación en Python (mantiene orden de inserción desde 3.7; keys de JSON son siempre string, en dict cualquier tipo hasheable). Claves duplicadas: se conserva la última. Métodos: `.items()`, `.keys()`, `.values()`, `.clear()`, `defaultdict`."}],"ejemplo":[{"t":"code","lang":"python","x":"from collections import defaultdict\npor_categoria = defaultdict(list)\nfor cat, prod in productos:\n    por_categoria[cat].append(prod)"}],"qa":[{"q":"¿Cómo se relacionan hash table, HashMap y dict, y qué pasa con claves duplicadas?","a":"Hash table = base; HashMap = estructura abstracta; dict = implementación en Python. Con claves duplicadas no hay error: se conserva la última."}]},{"title":"HashMap: usos prácticos y errores comunes","que":[{"t":"p","x":"Usos: caché/memoización, conteo de frecuencias, índices de base de datos, agrupación, configuración. Errores: claves mutables (deben ser inmutables y hasheables: str, número, tupla), sobreusar hashmaps, ignorar memoria, asumir orden (los dict modernos preservan inserción pero no depender de ello) y no manejar claves ausentes (usar `get`, `defaultdict` o `in`)."}],"ejemplo":[],"qa":[{"q":"¿Por qué las claves de un dict deben ser inmutables?","a":"Si una clave cambiara tras insertarse, el hashmap ya no la encontraría."}]},{"title":"Bucket y colisión","que":[{"t":"p","x":"Un bucket es una posición del array interno (un \"buzón\"). Una colisión ocurre cuando dos claves distintas dan el mismo bucket; es inevitable y no pierde datos (se resuelve, no se descarta). Python usa open addressing con probing (busca el siguiente hueco libre en un array compacto); otros lenguajes usan separate chaining (cada bucket apunta a una linked list). Analogía de los andenes: con todos los trenes en un andén, O(1) pasa a O(n); una buena función hash y agrandar la tabla lo evitan."}],"ejemplo":[],"qa":[{"q":"¿Qué es una colisión, se pierde el dato y qué estrategia usa Python?","a":"Dos claves distintas con el mismo índice; no se pierde el dato. Python usa open addressing con probing (prueba el siguiente bucket libre); otros, chaining."}]},{"title":"Binary Search Tree (BST)","que":[{"t":"p","x":"Árbol de nodos conectados por punteros; cada nodo tiene máximo dos hijos. Regla: izquierda menor, derecha mayor, lo que permite descartar la mitad en cada búsqueda (O(log n)). Frente al Hash Table busca más lento (O(log n) vs O(1) promedio) pero mantiene los datos ordenados. Buscar/insertar es recursivo."}],"ejemplo":[],"qa":[{"q":"¿Cuál es la regla de orden de un BST?","a":"Lo de la izquierda de un nodo es menor y lo de la derecha mayor."}]},{"title":"Heap (max-heap, min-heap) y Priority Queue","que":[{"t":"p","x":"Árbol cuya regla compara padre contra hijos (max-heap: padre mayor; min-heap: padre menor), por lo que la raíz es siempre el extremo. No sirve para buscar un valor cualquiera; sirve para acceso instantáneo al máximo/mínimo. Base de las Priority Queues y de Dijkstra. En Python: `heapq` sobre una lista."}],"ejemplo":[],"qa":[{"q":"¿Por qué no se puede buscar en un heap como en un BST y para qué sirve?","a":"Solo se sabe que ambos hijos son menores que el padre, no cuál es mayor entre sí. Sirve para acceso inmediato al máximo/mínimo (priority queues)."}]},{"title":"Caché LRU","que":[{"t":"p","x":"Caché de capacidad fija que expulsa el elemento menos recientemente usado; `get` también cuenta como uso y un valor `0` es válido. Se implementa con `OrderedDict`."}],"ejemplo":[],"qa":[{"q":"¿Qué expulsa una caché LRU al llenarse?","a":"El elemento usado hace más tiempo (menos recientemente usado)."}]},{"title":"Recorridos de árbol: pre, in y post-order","que":[{"t":"p","x":"Los tres son el mismo recorrido; cambia cuándo se anota el nodo. In-order de un BST sale ordenado; post-order es natural para borrar o cuando el padre necesita el resultado de los hijos."}],"ejemplo":[],"qa":[{"q":"¿Qué devuelve in-order en un BST?","a":"Los valores ordenados."}]},{"title":"Representación de árbol por niveles","que":[{"t":"p","x":"`construir(lista)` arma un árbol desde una lista por niveles con `None` como hueco, usando una cola; `Nodo(valor, izq, der)` como dataclass."}],"ejemplo":[],"qa":[{"q":"¿Qué representa `None` en la lista por niveles?","a":"Un hueco (hijo inexistente)."}]}]},{"title":"Recursión y búsqueda","concepts":[{"title":"Recursión y caso base","que":[{"t":"p","x":"Una función que se llama a sí misma sobre una versión más chica del problema hasta un caso base. Tres piezas: se llama a sí misma, el problema se achica, y hay caso base (la condición que detiene la cadena; si falta: `RecursionError`). Ej.: buscar en BST (casos base: valor encontrado o pointer `null`). Alternativa: iteración. Fibonacci, árboles y backtracking la usan."}],"ejemplo":[],"qa":[{"q":"¿Cuáles son las tres piezas de la recursión y qué pasa sin caso base?","a":"Se llama a sí misma, achica el problema en cada llamada y tiene un caso base. Sin caso base: `RecursionError`."}]},{"title":"Linear Search","que":[{"t":"p","x":"Recorrer uno por uno comparando hasta encontrar o terminar; sin suposición de orden. O(n) tiempo, O(1) espacio. Conviene en listas chicas, listas desordenadas buscadas una sola vez y estructuras sin acceso aleatorio (linked lists). Ordenar para buscar una vez cuesta más (O(n log n))."}],"ejemplo":[],"qa":[{"q":"¿Por qué usar Linear Search si Binary Search es más rápido?","a":"Porque binary requiere lista ordenada; ordenar para una sola búsqueda sale más caro."}]},{"title":"Búsqueda binaria (clásica)","que":[{"t":"p","x":"En un espacio ORDENADO o monótono, con límites `lo`/`hi` miras el medio y descartas la mitad: O(log n) (mejor caso O(1)). Pista: array ordenado/rotado o \"el mínimo/máximo valor que cumple\". Cuidado con `mid`, los límites (`lo <= hi`, `mid±1`), la lista vacía y los duplicados. Error clásico: `lo = mid` en vez de `mid + 1` provoca bucle infinito."}],"ejemplo":[{"t":"p","x":"`mid=(lo+hi)//2; if a[mid]<x: lo=mid+1 else: hi=mid-1`"}],"qa":[{"q":"¿Qué debe cumplir la entrada, qué coste tiene y por qué `lo = mid + 1`?","a":"Estar ordenada; O(log n). Con `lo = mid` el rango puede no achicarse y entra en bucle infinito."}]},{"title":"lower_bound: posición de inserción","que":[{"t":"p","x":"Siempre hay respuesta: se deja que los límites se crucen y `lo` queda en el sitio correcto. Devuelve el primer índice con `a[i] >= target`. Es el esqueleto reutilizable de todo el taller de búsqueda binaria."}],"ejemplo":[{"t":"code","lang":"python","x":"def lower_bound(a, target):\n    lo, hi = 0, len(a)\n    while lo < hi:\n        mid = (lo + hi) // 2\n        if a[mid] < target: lo = mid + 1\n        else: hi = mid\n    return lo"}],"qa":[{"q":"¿Qué devuelve `lower_bound` y dónde queda el resultado al terminar el bucle?","a":"El primer índice con `a[i] >= target`; queda en `lo`."}]},{"title":"Primera y última aparición (dos binarias)","que":[{"t":"p","x":"Al encontrar target se sigue buscando a izquierda (primera) o derecha (última) guardando el candidato; evita caminar O(n)."}],"ejemplo":[],"qa":[{"q":"¿Por qué no encontrar uno y caminar a los lados?","a":"Con muchos repetidos sería O(n)."}]},{"title":"Techo y siguiente letra (punto de quiebre)","que":[{"t":"p","x":"No se busca un valor sino el primer punto donde pasa de \"no cumple\" a \"cumple\": si cumple, se guarda y se sigue a la izquierda. \"Estrictamente mayor\" y lista circular se resuelven con `%`."}],"ejemplo":[],"qa":[{"q":"¿Cómo hacer circular el índice resultante?","a":"Con el operador módulo `%` sobre la longitud."}]},{"title":"Pico de montaña: monotonía sin orden","que":[{"t":"p","x":"La búsqueda binaria no exige orden sino monotonía: comparar el medio con su vecino derecho dice hacia qué lado está la cima."}],"ejemplo":[],"qa":[{"q":"¿Qué necesita realmente la búsqueda binaria?","a":"Monotonía (una señal de hacia qué lado ir), no necesariamente orden total."}]},{"title":"Array rotado: mínimo y búsqueda","que":[{"t":"p","x":"Un rotado son dos tramos ordenados; si `nums[mid] > nums[hi]` la costura está a la derecha. Para buscar, una de las dos mitades siempre está ordenada (comparando `nums[lo]` con `nums[mid]`)."}],"ejemplo":[],"qa":[{"q":"¿Cómo saber en qué tramo estás?","a":"Comparando `nums[mid]` con `nums[hi]`."}]},{"title":"Elemento único en array de parejas","que":[{"t":"p","x":"La monotonía está en los índices: antes del único las parejas empiezan en índice par, después en impar. Se fuerza `mid` a par y se compara con `mid+1`. O(log n) (XOR sería O(n))."}],"ejemplo":[],"qa":[{"q":"¿Dónde se rompe el patrón de parejas?","a":"Justo en el elemento único: desde ahí las parejas empiezan en índice impar."}]},{"title":"Búsqueda binaria sobre la respuesta","que":[{"t":"p","x":"Sin array: se busca en el rango de respuestas posibles, que es monótono (raíz entera 0..n; velocidad de Koko 1..max; capacidad de barco max..sum; \"minimizar el máximo\"). Se acotan `lo`/`hi` y se define un predicado monótono `factible(mid)`. Complejidad O(log n), o O(n·log(rango)) con verificador lineal. Usar `mid = lo + (hi-lo)//2`. También cubre arreglos rotados (identificar qué mitad está ordenada)."}],"ejemplo":[],"qa":[{"q":"¿Cómo se plantea binary search on answer?","a":"Acotando lo/hi de la respuesta y, con un verificador monótono `factible(mid)` (ej. `llega_a_tiempo(k)`), moviendo el límite hasta el óptimo."}]},{"title":"División con redondeo hacia arriba","que":[{"t":"p","x":"Horas por montón = ceil(montón / k); un montón de 7 a velocidad 4 son 2 horas."}],"ejemplo":[{"t":"p","x":"`(m + k - 1) // k`"}],"qa":[{"q":"¿Cómo hacer ceil de enteros sin `math`?","a":"`(a + b - 1) // b`."}]}]},{"title":"Ordenamiento","concepts":[{"title":"Criterio de ordenamiento y Selection Sort","que":[{"t":"p","x":"Para ordenar hay que definir primero el criterio (alfabético, por categoría...). Selection Sort: buscar el extremo de lo que queda sin ubicar, fijarlo y no tocarlo más (versión de César: ambos extremos a la vez). Mismo principio que recursión (el problema se achica)."}],"ejemplo":[],"qa":[{"q":"¿Qué hace Selection Sort en cada paso?","a":"Busca el mínimo de lo no ordenado y lo fija en su lugar."}]},{"title":"Bubble Sort","que":[{"t":"p","x":"Solo se intercambian vecinos: si están en mal orden se cambian y se avanza. Tras cada vuelta, el mayor \"burbujea\" al final. Siempre O(n²); útil solo para detectar si una lista ya está casi ordenada (una vuelta sin intercambios)."}],"ejemplo":[],"qa":[{"q":"¿Por qué se llama Bubble Sort?","a":"Porque en cada vuelta el mayor burbujea hacia el final."}]},{"title":"Insertion Sort","que":[{"t":"p","x":"Como un mazo de cartas: se toma el siguiente elemento (orden fijo) y se inserta donde corresponde en la parte ya ordenada. Rápido en listas chicas o casi ordenadas; Timsort lo usa para los pedazos chicos. Ej.: leaderboard."}],"ejemplo":[],"qa":[{"q":"¿Cuál es la regla clave de Insertion Sort?","a":"Siempre se toma el siguiente elemento (no se puede saltar) y se inserta en su sitio entre los ya ordenados."}]},{"title":"Merge Sort","que":[{"t":"p","x":"Divide y vencerás: corta la lista a la mitad recursivamente hasta un solo elemento (caso base, ya ordenado) y luego hace merge comparando solo los primeros elementos disponibles de cada mitad, sacando el menor; cuando una mitad se vacía, el resto de la otra entra tal cual. Comparar por posición fija no funciona."}],"ejemplo":[],"qa":[{"q":"¿Cómo se hace el merge de dos mitades ordenadas?","a":"Comparando el frente de cada mitad, sacando el menor y avanzando en esa mitad hasta vaciarlas."}]},{"title":"Quick Sort","que":[{"t":"p","x":"Divide y vencerás con un pivote: reorganiza menores a la izquierda y mayores a la derecha, y repite en cada grupo (caso base: un elemento). El pivote cumple un rol parecido a un nodo de BST pero se elige de nuevo en cada pedazo. Peor caso O(n²)."}],"ejemplo":[],"qa":[{"q":"¿En qué difiere Quick Sort de Merge Sort?","a":"Elige un pivote y particiona alrededor de él en lugar de cortar ciegamente por la mitad y juntar."}]},{"title":"Heap Sort","que":[{"t":"p","x":"Como Selection Sort pero con un max-heap: se saca la raíz (el máximo) al final, se tapa el hueco con el último elemento del heap y se arregla con sift-down comparando con el hijo mayor. Garantiza O(n log n) siempre y sin memoria extra."}],"ejemplo":[],"qa":[{"q":"En el sift-down, ¿con qué hijo se compara y por qué?","a":"Con el mayor, para no dejar sin revisar al que podría seguir rompiendo la regla."}]},{"title":"Timsort","que":[{"t":"p","x":"Algoritmo de `sorted()`/`.sort()` de Python (de Tim Peters): híbrido de merge e insertion sort que detecta runs ya ordenados (los invertidos se dan vuelta), alarga los muy cortos con insertion sort y mergea. Peor O(n log n), mejor O(n). Es estable (los empates conservan orden), lo que permite ordenar por varios criterios sucesivos."}],"ejemplo":[],"qa":[{"q":"¿Qué significa que Timsort sea estable?","a":"Elementos iguales conservan su orden original, útil para ordenar por criterios en cascada."}]}]},{"title":"Patrones de algoritmos: método","concepts":[{"title":"Patrones de coding (cómo usarlos y temario de entrevista)","que":[{"t":"p","x":"\"Moldes\" de solución que se repiten en LeetCode/Exercism. La habilidad a entrenar es leer la pista que delata cada patrón. Método: preguntarse por la forma del problema (¿ordenado? ¿más largo/corto? ¿todas las combinaciones? ¿k-ésimo? ¿dependencias?), abrir el patrón, confirmar por la pista, aplicar la plantilla y ajustar; luego leer la señal, memorizar la plantilla, resolver 3-5 guiados y 3-5 a ciegas. Temario de entrevistas: árboles binarios y recorridos, BFS (cola) vs DFS (pila/recursión), DP (memorizar subresultados), Dijkstra, backtracking (sudoku/n-reinas), ordenamientos O(n²) vs O(n log n)."}],"ejemplo":[],"qa":[{"q":"¿Cuál es la habilidad central para resolver problemas por patrones?","a":"Reconocer la pista (señal reveladora) que indica qué patrón calza con la forma del problema."}]},{"title":"Cheatsheet de detección rápida","que":[{"t":"p","x":"Mapa pista -> patrón: arreglo ordenado + par = Two Pointers; subarreglo/substring más largo/corto = Sliding Window; lista enlazada + ciclo/medio = Fast & Slow; camino más corto sin pesos = BFS; todas las combinaciones = Backtracking; ordenado/rotado = Binary Search; minimizar el máximo = binary search on answer; rangos solapados = Merge Intervals/Sweep line; k más grandes = Top K; subestructura + subproblemas repetidos = DP; 1..n con faltante/duplicado = Cyclic Sort; siguiente mayor = Monotonic Stack; prefijos = Trie; conectividad = Union-Find; prerequisitos = Topological Sort; pesos en grafo = Dijkstra/Bellman-Ford/Floyd; n<=20 asignación = Bitmask DP; mediana en stream = Two Heaps; suma máxima contigua = Kadane."}],"ejemplo":[],"qa":[{"q":"\"Minimiza el máximo / maximiza el mínimo\": ¿qué patrón?","a":"Búsqueda binaria sobre la respuesta."}]},{"title":"Taller por patrones: practicar haciendo","que":[{"t":"p","x":"Cada archivo trae enunciado, ejemplos, pista, stub con `# TODO` y tests que imprimen `[OK]` o `[..] pendiente`. El orden de resultados suele dar igual (se ordenan antes de comparar). Siempre decir en voz alta la complejidad (Big O) de cada solución."}],"ejemplo":[],"qa":[{"q":"¿Qué debes decir después de cada solución?","a":"Su complejidad temporal."}]}]},{"title":"Arrays, strings y hashing","concepts":[{"title":"Hashing patterns (Two Sum, frecuencias, rolling hash)","que":[{"t":"p","x":"\"Existe un par/triple con propiedad X\", anagramas, duplicados: hash map en O(n). Rolling hash compara subcadenas en O(1) por hash."}],"ejemplo":[],"qa":[{"q":"¿Qué tipo de problemas se resuelven con hash map en O(n)?","a":"Existencia de par/triple con propiedad, anagramas, duplicados y frecuencias."}]},{"title":"Two Sum con hash map (O(n))","que":[{"t":"p","x":"Recorres una vez guardando `valor→índice`; para cada `x` preguntas si `objetivo - x` ya fue visto. Consulta el dict ANTES de guardar el número actual para no usar el mismo elemento dos veces. La versión ingenua con dos bucles es O(n²)."}],"ejemplo":[{"t":"p","x":"`if objetivo - n in vistos: return (vistos[objetivo-n], j)`"}],"qa":[{"q":"¿Por qué Two Sum con diccionario es mejor que con dos bucles?","a":"Pasa de O(n²) a O(n): la búsqueda del complemento en el dict es O(1) en vez de recorrer el resto de la lista."}]},{"title":"Agrupar anagramas con \"firma\"","que":[{"t":"p","x":"Dos palabras son anagramas si tienen las mismas letras ordenadas; esa firma `\"\".join(sorted(p))` sirve de clave de un `defaultdict(list)`."}],"ejemplo":[],"qa":[{"q":"¿Qué usas como clave para agrupar anagramas?","a":"Las letras de la palabra ordenadas (`\"\".join(sorted(p))`)."}]},{"title":"Duplicados en orden de primera aparición","que":[{"t":"p","x":"Contar con un dict (que recuerda el orden de inserción) y devolver las claves con conteo > 1."}],"ejemplo":[],"qa":[{"q":"¿Qué propiedad del dict mantiene el orden de primera aparición?","a":"Que desde 3.7 conserva el orden de inserción."}]},{"title":"Parsear líneas de log key=value y top-k","que":[{"t":"p","x":"`linea.split()` separa campos y `parte.partition(\"=\")` clave/valor; filtrar `status=200`, ignorar líneas inválidas, contar con `Counter` y devolver k más visitados con desempate alfabético."}],"ejemplo":[],"qa":[{"q":"¿Qué método separa `path=/x` en clave y valor?","a":"`str.partition(\"=\")`."}]},{"title":"Rotar una lista k posiciones","que":[{"t":"p","x":"`k %= len(lista)` (cuidado con lista vacía: módulo 0) y `lista[-k:] + lista[:-k]`; `k=0` es caso especial porque `lista[-0:]` es toda la lista. Devuelve una lista nueva y rechaza `k` negativo."}],"ejemplo":[],"qa":[{"q":"¿Por qué `lista[-0:]` es un problema al rotar?","a":"Porque `-0` es 0 y devuelve toda la lista, así que hay que tratar `k=0` aparte."}]},{"title":"Palíndromo y palíndromo alfanumérico","que":[{"t":"p","x":"Comparar extremos hacia el centro con dos punteros; en la variante alfanumérica se saltan caracteres no alfanuméricos (`isalnum`) y se compara en minúsculas (`lower`). Alternativa simple: limpiar y comparar con el reverso. El vacío es palíndromo. En JS se quitan tildes con `normalize('NFD')` + regex."}],"ejemplo":[{"t":"p","x":"`limpio = [c.lower() for c in s if c.isalnum()]; limpio == limpio[::-1]`"}],"qa":[{"q":"¿Cómo ignoras puntuación y mayúsculas al comprobar un palíndromo (con dos punteros)?","a":"Filtras con `isalnum()` y minúsculas; con dos punteros avanzas el que cae en un carácter no alfanumérico sin comparar."}]},{"title":"Máxima ganancia en una pasada","que":[{"t":"p","x":"Mantener el precio mínimo visto hasta ahora; en cada día la mejor venta es `precio - minimo`. O(n) en una sola pasada."}],"ejemplo":[],"qa":[{"q":"¿Qué dos valores llevas mientras recorres precios?","a":"El mínimo visto y la mejor ganancia encontrada."}]},{"title":"Prefix Sum","que":[{"t":"p","x":"Precalcular sumas acumuladas para que cualquier suma de rango sea `pref[j]-pref[i]` en O(1). Pista: muchas consultas de suma de rango o subarreglo con suma exactamente K (combinado con hash map). No sirve si el array cambia (Segment/Fenwick) ni para el \"mejor\" subarreglo (Kadane). Existe versión 2D por inclusión-exclusión."}],"ejemplo":[{"t":"code","lang":"python","x":"count, pref, seen = 0, 0, {0: 1}\nfor x in a:\n    pref += x\n    count += seen.get(pref - k, 0)\n    seen[pref] = seen.get(pref, 0) + 1"}],"qa":[{"q":"Muchas consultas de suma i..j, ¿qué patrón?","a":"Prefix Sum: preproceso O(n) y cada rango sale de una resta en O(1)."}]},{"title":"Difference Array","que":[{"t":"p","x":"Para muchas operaciones \"sumar x al rango [l..r]\" y una sola lectura final: se actualizan solo los bordes en O(1) (`d[l]+=x; d[r+1]-=x`) y se reconstruye con suma de prefijos. Total O(q+n)."}],"ejemplo":[],"qa":[{"q":"¿Cómo se aplica un incremento a un rango en O(1)?","a":"`d[l] += x; d[r+1] -= x` y luego se reconstruye con suma acumulada."}]},{"title":"Kadane (Maximum Subarray) y variantes","que":[{"t":"p","x":"En cada elemento decides extender la racha o arrancar una nueva: `actual = max(x, actual + x)`; guardas el mejor global. O(n)/O(1). Es DP simple. Variantes: circular (`max(kadane, total + kadane(-a))`), producto máximo (guardar también el mínimo por los negativos) y 2D (fijar filas y aplicar Kadane a la columna de sumas)."}],"ejemplo":[{"t":"code","lang":"python","x":"actual = best = a[0]\nfor x in a[1:]:\n    actual = max(x, actual + x)\n    best = max(best, actual)"}],"qa":[{"q":"\"Suma máxima de un subarreglo contiguo\", ¿qué patrón?","a":"Kadane: extender o reiniciar la racha en cada elemento, O(n)."}]},{"title":"Cyclic Sort","que":[{"t":"p","x":"Cuando los números son un rango conocido 1..n (o 0..n-1), cada valor sabe su índice (`a[i]` debe ir en `a[i]-1`); se intercambia hasta colocarlos. El primer índice que no calza delata el faltante o duplicado. O(n) tiempo, O(1) espacio."}],"ejemplo":[{"t":"code","lang":"python","x":"i = 0\nwhile i < len(a):\n    j = a[i] - 1\n    if a[i] != a[j]: a[i], a[j] = a[j], a[i]\n    else: i += 1"}],"qa":[{"q":"El array tiene n números en 1..n y piden el que falta, ¿qué patrón?","a":"Cyclic Sort, O(n) y O(1) de espacio."}]},{"title":"Bucket Sort / Counting Sort / Dutch Flag","que":[{"t":"p","x":"Cuando el rango de valores es pequeño y conocido, O(n+k) en vez de O(n log n). Top K frecuentes: bucket por frecuencia. Dutch National Flag: partición en 3 con punteros `lo, mid, hi` (Sort Colors)."}],"ejemplo":[],"qa":[{"q":"¿Cómo resolver Top K frecuentes en O(n)?","a":"Con buckets indexados por frecuencia."}]},{"title":"Matrix Traversal","que":[{"t":"p","x":"Operaciones 2D: espiral (cuatro punteros top/bot/left/right), rotar, transponer, diagonales y contar regiones conectadas (islas) con DFS/BFS marcando visitado. O(n·m)."}],"ejemplo":[],"qa":[{"q":"¿Qué se usa para recorrer una matriz en espiral?","a":"Cuatro límites (top, bottom, left, right) que se van cerrando."}]}]},{"title":"Two Pointers","concepts":[{"title":"Two Pointers","que":[{"t":"p","x":"Dos índices recorren la estructura desde posiciones distintas según una regla, evitando el doble `for` O(n²). Pista: array/string ordenado donde buscas un par (suma, palíndromo) o comparas desde los extremos. Variantes: convergentes (extremos) y lector/escritor (misma dirección, in-place). Analogía: manos abiertas que se cierran. Usar `while l < r`, no `i != j`. O(n) tiempo, O(1) espacio."}],"ejemplo":[{"t":"code","lang":"python","x":"def two_sum_sorted(a, target):\n    l, r = 0, len(a) - 1\n    while l < r:\n        s = a[l] + a[r]\n        if s == target: return [l, r]\n        if s < target: l += 1\n        else: r -= 1\n    return []"}],"qa":[{"q":"Te dan un array o string ORDENADO y buscas un par que cumple algo, ¿qué patrón y qué complejidad?","a":"Two Pointers: dos índices desde posiciones distintas, O(n) tiempo y O(1) espacio."}]},{"title":"Two pointers: invertir in-place","que":[{"t":"p","x":"Un puntero al inicio y otro al final; se intercambian y se acercan hasta cruzarse (paran cuando se cruzan). Sin lista nueva y con O(1) de memoria extra."}],"ejemplo":[{"t":"p","x":"`[a[i], a[j]] = [a[j], a[i]]; i++; j--`"}],"qa":[{"q":"¿Cómo inviertes un array in-place sin `reverse()` y cuándo paran los punteros?","a":"Dos índices en los extremos que se intercambian y avanzan hacia el centro; paran cuando se cruzan."}]},{"title":"Subsecuencia (mismo sentido)","que":[{"t":"p","x":"Dos punteros en el mismo sentido: el de `t` avanza siempre y el de `s` solo al hacer match; `s` es subsecuencia si su puntero llega al final."}],"ejemplo":[],"qa":[{"q":"¿Cuándo `s` es subsecuencia de `t`?","a":"Cuando todas sus letras aparecen en `t` en orden aunque no estén pegadas."}]},{"title":"Invertir solo las vocales","que":[{"t":"p","x":"Un puntero por extremo; el que no apunta a vocal avanza; cuando ambos apuntan a vocales se intercambian. Los strings no se mutan: se trabaja sobre `list(s)`."}],"ejemplo":[],"qa":[{"q":"¿Por qué convertir el string a lista?","a":"Los strings son inmutables."}]},{"title":"Two Sum en array ordenado","que":[{"t":"p","x":"Con orden: suma corta -> sube el izquierdo; suma pasada -> baja el derecho. O(n), sin volver atrás."}],"ejemplo":[],"qa":[{"q":"¿Qué haces si la suma de los extremos es mayor que el target?","a":"Mueves el puntero derecho hacia la izquierda."}]},{"title":"Par con suma más cercana","que":[{"t":"p","x":"Igual que Two Sum pero guardando la mejor suma vista (menor distancia a target) y moviendo punteros según se pase o falte."}],"ejemplo":[],"qa":[{"q":"¿Qué guardas en lugar de parar al primer acierto?","a":"La mejor suma (menor `abs(suma - target)`)."}]},{"title":"Cuadrados de un array ordenado (O(n))","que":[{"t":"p","x":"El mayor cuadrado está en un extremo; se compara y se escribe el mayor al final del resultado."}],"ejemplo":[],"qa":[{"q":"¿Dónde está el cuadrado más grande si hay negativos?","a":"En uno de los extremos."}]},{"title":"Container With Most Water","que":[{"t":"p","x":"Empezar con los extremos; el área la limita la línea más baja, así que siempre se mueve el puntero de la más baja; guardar el máximo."}],"ejemplo":[],"qa":[{"q":"¿Qué puntero mueves y por qué?","a":"El de la línea más baja, porque la más alta no puede mejorar quedándose."}]},{"title":"Contar pares con suma menor que target","que":[{"t":"p","x":"Si `nums[izq]+nums[der] < target`, todos los de `izq+1..der` también emparejan: se suman `der - izq` de golpe y `izq++`; si no, `der--`."}],"ejemplo":[],"qa":[{"q":"¿Cuántos pares sumas de golpe cuando la suma de extremos cumple?","a":"`der - izq`."}]},{"title":"Lento/rápido: quitar duplicados y quitar elemento","que":[{"t":"p","x":"El rápido recorre; el lento marca dónde escribir el próximo elemento que se queda. Devuelve la nueva longitud `k`. Aplica a quitar duplicados de un array ordenado y quitar todas las apariciones de un valor."}],"ejemplo":[],"qa":[{"q":"¿Qué marca el puntero lento?","a":"La posición donde se escribirá el próximo elemento válido."}]},{"title":"Mover ceros al final","que":[{"t":"p","x":"El lento apunta a la próxima posición para un no-cero; cada no-cero encontrado por el rápido se intercambia con el lento; mantiene el orden relativo."}],"ejemplo":[],"qa":[{"q":"¿Qué se intercambia y cuándo?","a":"Cada no-cero que halla el rápido con la posición del lento."}]},{"title":"Fusionar dos listas ordenadas (merge)","que":[{"t":"p","x":"Un puntero por lista; se mete el menor de los frentes y se avanza solo ese; al acabar una se agrega el resto de la otra. Es el paso merge de Merge Sort."}],"ejemplo":[],"qa":[{"q":"¿Qué haces cuando una lista se agota?","a":"Agregas el resto de la otra tal cual."}]},{"title":"Dutch flag (3 punteros)","que":[{"t":"p","x":"`bajo`, `alto` e `i`: 0 -> swap con `bajo` y avanzan; 2 -> swap con `alto` y baja `alto` sin avanzar `i`; 1 -> avanza `i`. Una pasada, sin sort."}],"ejemplo":[],"qa":[{"q":"¿Por qué no avanza `i` tras un swap con `alto`?","a":"El valor que llegó desde `alto` aún no se ha examinado."}]},{"title":"3Sum y variantes (cercana, contar menores)","que":[{"t":"p","x":"Ordenar, fijar un número y aplicar Two Sum ordenado al resto; saltar duplicados en el fijo y al mover punteros. 3Sum closest guarda la mejor suma; contar triples menores usa el truco de conteo `der - izq`."}],"ejemplo":[],"qa":[{"q":"¿Cómo evitas triples repetidos en 3Sum?","a":"Ordenas y saltas valores repetidos en el número fijo y al mover los punteros."}]},{"title":"Trapping Rain Water","que":[{"t":"p","x":"Dos punteros con `maxIzq` y `maxDer`; se avanza el lado de menor máximo; si la barra es menor que su máximo, la diferencia es agua. Cabe `min(maxIzq,maxDer) - altura`."}],"ejemplo":[],"qa":[{"q":"¿Qué lado avanzas y por qué?","a":"El de menor máximo, porque ese lado decide el agua."}]},{"title":"Comparar con backspace","que":[{"t":"p","x":"Recorrer ambos strings de derecha a izquierda con un contador de borrados pendientes por `#`, comparando solo los caracteres que sobreviven (O(1) memoria)."}],"ejemplo":[],"qa":[{"q":"¿Por qué recorrer de derecha a izquierda?","a":"Así sabes cuántos caracteres saltar al ver `#` sin construir el string."}]}]},{"title":"Sliding Window","concepts":[{"title":"Sliding Window","que":[{"t":"p","x":"Ventana contigua que crece por la derecha y encoge por la izquierda sin retroceder, O(n). Pista: subarreglo/substring contiguo más largo/corto/con suma X/con a lo más K distintos. Ventana fija (entra uno, sale uno) o dinámica (contraer mientras viole la condición). Caso especializado de Two Pointers (ambos hacia adelante)."}],"ejemplo":[{"t":"code","lang":"python","x":"def longest_unique(s):\n    seen, l, best = {}, 0, 0\n    for r, ch in enumerate(s):\n        if ch in seen and seen[ch] >= l: l = seen[ch] + 1\n        seen[ch] = r\n        best = max(best, r - l + 1)\n    return best"}],"qa":[{"q":"Piden el subarreglo CONTIGUO más largo/corto que cumple X, ¿qué patrón?","a":"Sliding Window, O(n)."}]},{"title":"Sliding Window vs Two Pointers","que":[{"t":"p","x":"Two Pointers compara/mueve desde extremos de algo ordenado; Sliding Window mide un rango contiguo que crece y encoge según una condición."}],"ejemplo":[],"qa":[{"q":"Sliding Window y Two Pointers se parecen. ¿Cuándo cada uno?","a":"Two Pointers: extremos de algo ordenado. Sliding Window: rango contiguo que crece/encoge según una condición."}]},{"title":"Sliding window: ventana fija","que":[{"t":"p","x":"Especialización de two pointers hacia adelante. Al mover la ventana se suma el que entra y se resta el que sale: O(n) en lugar de O(n·k). Hay n-k+1 ventanas. Aplica a suma máxima de k, promedios y más."}],"ejemplo":[],"qa":[{"q":"¿Cómo evitas recalcular la suma de cada ventana?","a":"Sumas el elemento que entra y restas el que sale."}]},{"title":"Permutación del patrón y todos los anagramas","que":[{"t":"p","x":"Ventana fija de tamaño `len(patron)` comparando contadores (`Counter ==`). Para devolver todas las posiciones y bajar a O(1) por paso, se lleva un contador de letras ya cuadradas."}],"ejemplo":[],"qa":[{"q":"¿Qué estructura compara si dos ventanas son permutación?","a":"Un contador (`Counter`) de letras."}]},{"title":"Ventana variable: subarreglo mínimo con suma >= target","que":[{"t":"p","x":"El borde derecho crece hasta cumplir; el izquierdo encoge mientras siga cumpliendo (`while`, no `if`). Requiere enteros positivos: con negativos, encoger podría aumentar la suma."}],"ejemplo":[],"qa":[{"q":"¿Por qué se exigen enteros positivos?","a":"Con negativos encoger no garantiza reducir la suma y el mecanismo se rompe."}]},{"title":"Substring más largo sin repetir","que":[{"t":"p","x":"Mantienes una ventana `[inicio, i]` y un dict `caracter -> última posición`; al ver un repetido, el borde izquierdo solo se mueve si la posición previa está dentro de la ventana: `inicio = ultima[c] + 1` si `ultima[c] >= inicio` (caso \"abba\"). O(n)."}],"ejemplo":[],"qa":[{"q":"¿Cómo y cuándo actualizas el inicio de la ventana al ver un carácter repetido?","a":"`inicio = ultima[c] + 1`, solo si `ultima[c] >= inicio` (la posición anterior está dentro de la ventana actual)."}]},{"title":"K distintos, frutas en cestas y unos consecutivos","que":[{"t":"p","x":"\"Como mucho k distintos\" encoge con `len(contador) > k`: restar y borrar la clave en 0. Frutas en cestas es k=2 disfrazado; voltear k ceros equivale a \"ventana con como mucho k ceros\"."}],"ejemplo":[],"qa":[{"q":"¿Por qué borrar la letra del dict al llegar a 0?","a":"Si no, `len()` miente y la ventana no vuelve a crecer."}]},{"title":"Reemplazo de caracteres: condición con la letra más frecuente","que":[{"t":"p","x":"Una ventana vale si `longitud - frecuencia_máxima <= k`; lo que sobra es lo que se reemplazaría."}],"ejemplo":[],"qa":[{"q":"¿Cuál es la condición de ventana válida?","a":"`longitud - repeticiones de la letra más frecuente <= k`."}]},{"title":"Ventana mínima que contiene el patrón","que":[{"t":"p","x":"Crece hasta ser válida y luego encoge mientras siga válida anotando la mejor; se usa un contador `faltan` para evitar comparar contadores enteros. Letras de sobra no invalidan."}],"ejemplo":[],"qa":[{"q":"¿Para qué sirve el número `faltan`?","a":"Saber en O(1) si la ventana ya cubre todo el patrón."}]},{"title":"Contar subarreglos con producto menor que k","que":[{"t":"p","x":"Si la ventana `[izq..der]` es válida aporta `der - izq + 1` subarreglos nuevos terminados en `der`; al encoger se divide por el que sale."}],"ejemplo":[],"qa":[{"q":"¿Cuántos subarreglos nuevos aporta una ventana válida?","a":"Su longitud (`der - izq + 1`)."}]},{"title":"Monotonic Stack / Queue","que":[{"t":"p","x":"Pila que mantiene orden (creciente o decreciente); al llegar un elemento que lo rompe, se sacan y resuelven los que esperaban. Pista: siguiente/anterior mayor o menor, temperaturas, histogramas. Colapsa O(n²) a O(n). Pila decreciente -> siguiente mayor; creciente -> siguiente menor. La cola monotónica (deque) da el máximo de una ventana de tamaño k."}],"ejemplo":[{"t":"code","lang":"python","x":"res, stack = [0]*len(t), []\nfor i, temp in enumerate(t):\n    while stack and t[stack[-1]] < temp:\n        j = stack.pop(); res[j] = i - j\n    stack.append(i)"}],"qa":[{"q":"\"Para cada elemento, ¿el siguiente mayor?\", ¿qué patrón?","a":"Monotonic Stack: una pila que mantiene orden y resuelve a los que esperaban; O(n)."}]}]},{"title":"Intervalos","concepts":[{"title":"Merge Intervals (fusionar intervalos)","que":[{"t":"p","x":"Ordenar los rangos por inicio y fusionar con el anterior si `start <= fin acumulado` (extender con `max`); si no, añadir uno nuevo. No modifiques la entrada. O(n log n). Meeting Rooms II se resuelve con heap o sweep line."}],"ejemplo":[{"t":"code","lang":"python","x":"intervals.sort(key=lambda x: x[0])\nout = [intervals[0]]\nfor s, e in intervals[1:]:\n    if s <= out[-1][1]: out[-1][1] = max(out[-1][1], e)\n    else: out.append([s, e])"}],"qa":[{"q":"Rangos [inicio, fin] que hay que fusionar, ¿qué patrón y qué paso es clave?","a":"Merge Intervals; ordenar por inicio."}]},{"title":"Interval List Manipulation (intersección e inserción)","que":[{"t":"p","x":"Con listas de intervalos ordenadas por inicio: fusionar, insertar, detectar solapamiento o intersectar dos listas con dos punteros (`lo = max(inicios)`, `hi = min(fines)`; avanzar el que termina antes). O(n) si ya están ordenadas."}],"ejemplo":[],"qa":[{"q":"¿Cómo se intersectan dos listas de intervalos ordenadas?","a":"Con dos punteros: intersección `[max(inicios), min(fines)]` y se avanza el que termina primero."}]},{"title":"Sweep Line (línea de barrido)","que":[{"t":"p","x":"Convertir intervalos en eventos (+1 al inicio, -1 al fin), ordenarlos y llevar un contador corriente; el máximo es la concurrencia máxima (salas mínimas, skyline). O(n log n)."}],"ejemplo":[],"qa":[{"q":"¿Cómo se calcula el máximo de eventos simultáneos?","a":"Con eventos +1/-1 ordenados por tiempo y un contador corriente cuyo máximo es el resultado."}]}]},{"title":"Listas enlazadas","concepts":[{"title":"Fast & Slow Pointers (tortuga y liebre)","que":[{"t":"p","x":"Dos punteros a velocidad 1 y 2 sobre una linked list: si hay ciclo se encuentran; si `fast` llega al final, `slow` está en el medio. O(n)/O(1), sin set de visitados. Para hallar el inicio del ciclo se reinicia uno desde `head` y ambos avanzan a 1 paso. También sirve para Happy Number y Find the Duplicate."}],"ejemplo":[{"t":"code","lang":"python","x":"slow = fast = head\nwhile fast and fast.next:\n    slow = slow.next; fast = fast.next.next\n    if slow is fast: return True\nreturn False"}],"qa":[{"q":"¿Cómo se detecta un ciclo en una linked list con O(1) de espacio?","a":"Con Fast & Slow Pointers: si el rápido alcanza al lento hay ciclo."}]},{"title":"In-place Reversal: invertir una lista enlazada","que":[{"t":"p","x":"Invertir una lista (o un tramo) dando vuelta los punteros `next` con `prev`, `curr` y `next`; guardar `next` ANTES de romper el enlace (si no, pierdes el resto). O(n)/O(1). Distingue a quien entiende referencias."}],"ejemplo":[{"t":"code","lang":"python","x":"prev, curr = None, head\nwhile curr:\n    nxt = curr.next\n    curr.next = prev\n    prev, curr = curr, nxt\nreturn prev"}],"qa":[{"q":"¿Qué error clásico hay al invertir una lista y por qué guardar `next` antes?","a":"Perder el resto de la lista: al cambiar el puntero pierdes el acceso al siguiente si no lo guardaste antes."}]}]},{"title":"Árboles y grafos (DFS y BFS)","concepts":[{"title":"DFS (Depth-First Search) y contar islas","que":[{"t":"p","x":"Va a fondo por un camino y retrocede; usa pila explícita o el call stack vía recursión. Pista: recorrer todo, contar componentes/islas, ver si existe un camino, traversals In/Pre/Post-order. O(V+E)/O(V). No garantiza el camino más corto; en grafos muy profundos puede dar `RecursionError` (hacerlo iterativo). En grid: los vecinos son las 4 celdas adyacentes; al pisar un `1` sin visitar se suma una isla y un DFS la hunde (marca como agua) para no recontar ni recursar infinitamente."}],"ejemplo":[{"t":"code","lang":"python","x":"def dfs(r, c):\n    if r < 0 or r >= R or c < 0 or c >= C or grid[r][c] != '1': return\n    grid[r][c] = '0'\n    dfs(r+1, c); dfs(r-1, c); dfs(r, c+1); dfs(r, c-1)"}],"qa":[{"q":"Contar islas/componentes o ver si existe camino, ¿qué patrón y para qué se marca visitado?","a":"DFS: ir a fondo y retroceder con pila/recursión. Se marca visitado para no recontar y evitar recursión infinita."}]},{"title":"Profundidad máxima (recursión que devuelve)","que":[{"t":"p","x":"Mi profundidad = 1 + la del hijo más profundo; árbol vacío = 0. Es post-order."}],"ejemplo":[],"qa":[{"q":"¿Qué devuelve la recursión de profundidad en un árbol vacío?","a":"0."}]},{"title":"DFS que arrastra estado: suma de camino y todos los caminos","que":[{"t":"p","x":"Se baja \"lo que queda por sumar\"; el caso base es una hoja (sin hijos), no `None`. Para todos los caminos, el camino actual se apila al entrar y se desapila al salir: esqueleto de backtracking."}],"ejemplo":[],"qa":[{"q":"¿Qué es una hoja?","a":"Un nodo sin ningún hijo (un nodo con un hijo no lo es)."}]},{"title":"Invertir árbol y comparar dos árboles","que":[{"t":"p","x":"Espejo: intercambiar hijos de cada nodo y confiar en la recursión. Iguales: bajar por ambos a la vez; ambos `None` -> True, solo uno -> False (detecta forma distinta)."}],"ejemplo":[],"qa":[{"q":"¿Qué caso base detecta árboles de forma distinta?","a":"Que solo uno de los dos nodos sea `None`."}]},{"title":"Área de isla y flood fill","que":[{"t":"p","x":"El DFS devuelve cuántas celdas hundió (`1 + suma de vecinos`). Flood fill: \"visitado\" es \"ya no tiene el color original\"; trampa: si el color nuevo es el original hay recursión infinita."}],"ejemplo":[],"qa":[{"q":"¿Qué trampa tiene flood fill?","a":"Si el color nuevo es igual al original nunca se marca como visitado y recursa infinitamente."}]},{"title":"Componentes conexas y lista de adyacencia","que":[{"t":"p","x":"Misma estructura que islas, pero los vecinos salen de una lista de adyacencia (dict de listas); un grafo no dirigido guarda cada arista en los dos sentidos; un nodo suelto es un grupo."}],"ejemplo":[],"qa":[{"q":"¿Cómo se guarda una arista no dirigida?","a":"En ambos sentidos en la lista de adyacencia."}]},{"title":"BFS (Breadth-First Search) y recorrido por niveles","que":[{"t":"p","x":"Explora por niveles usando una cola (FIFO, `collections.deque` con `popleft`); la primera vez que llegas a algo es por el camino más corto sin pesos. Plantilla: cola + `visited`; para separar niveles, medir `len(q)` antes de cada vuelta (esos son los nodos del piso). Vista derecha = último de cada nivel. Multi-source: inicializar la cola con todos los orígenes. O(V+E)/O(V). No sirve con pesos (Dijkstra)."}],"ejemplo":[{"t":"code","lang":"python","x":"q, out = deque([root]), []\nwhile q:\n    level = []\n    for _ in range(len(q)):\n        node = q.popleft(); level.append(node.val)\n        q.extend(c for c in (node.left, node.right) if c)\n    out.append(level)"}],"qa":[{"q":"\"Camino MÁS CORTO\" en grafo sin pesos o recorrido por niveles, ¿qué patrón y cómo separas los pisos?","a":"BFS con una cola; tomas `len(cola)` al empezar la vuelta para delimitar el nivel."}]},{"title":"BFS para profundidad mínima","que":[{"t":"p","x":"La primera hoja que sale de la cola ya es la más cercana, por eso BFS existe. Trampa: `1 + min(izq, der)` miente si un lado es `None` (un hijo único no es hoja)."}],"ejemplo":[],"qa":[{"q":"¿Por qué BFS es mejor para el camino más corto a una hoja?","a":"La primera hoja encontrada ya es la más cercana, sin explorar todo."}]},{"title":"BFS multi-fuente (naranjas podridas)","que":[{"t":"p","x":"Se meten todas las fuentes en la cola al inicio; el nivel del BFS es el minuto. Se cuentan las sanas y si queda alguna al final es inalcanzable (-1); sin sanas son 0 minutos."}],"ejemplo":[],"qa":[{"q":"¿Qué representa el nivel del BFS?","a":"El tiempo (minutos) de propagación."}]},{"title":"BFS vs DFS","que":[{"t":"p","x":"BFS para el camino más corto sin pesos y por niveles (cola); DFS para ir a fondo, contar componentes o ver si existe camino (pila/recursión)."}],"ejemplo":[],"qa":[{"q":"BFS y DFS resuelven recorridos. ¿Cuándo cada uno y qué estructura usa cada uno?","a":"BFS (cola): camino más corto sin pesos / niveles. DFS (pila o recursión): profundidad, componentes, existencia de camino."}]},{"title":"Topological Sort","que":[{"t":"p","x":"Ordenar nodos de un DAG para que cada tarea vaya antes que las que dependen de ella. Kahn: contar in-degree, cola con los de grado 0, restar a los vecinos; si no se procesan todos hay ciclo. Alternativa: DFS con 3 colores (blanco/gris/negro; back-edge = ciclo). Para orden lexicográfico usar min-heap. O(V+E)."}],"ejemplo":[],"qa":[{"q":"¿Cómo detecta un ciclo el algoritmo de Kahn?","a":"Si al final no se procesaron todos los nodos (`len(order) != V`), hay un ciclo."}]},{"title":"Union-Find (Disjoint Set)","que":[{"t":"p","x":"Mantiene grupos con un representante (raíz); `find` sube a la raíz y `union` cuelga una raíz bajo otra. Con path compression y union by rank/size es casi O(1) (α(n)). Si al unir ya tenían la misma raíz, esa arista cierra un ciclo. Pista: componentes conexas, ciclo en grafo no dirigido, MST con Kruskal."}],"ejemplo":[{"t":"code","lang":"python","x":"def find(self, x):\n    while self.parent[x] != x:\n        self.parent[x] = self.parent[self.parent[x]]\n        x = self.parent[x]\n    return x"}],"qa":[{"q":"\"¿A y B están conectados?\" o ciclo en grafo NO dirigido, ¿qué patrón?","a":"Union-Find con path compression: casi O(1) por operación."}]},{"title":"Detección de ciclos","que":[{"t":"p","x":"Grafo dirigido: DFS 3 colores o Kahn; no dirigido: DFS con padre o Union-Find; secuencia/linked list: Floyd (tortoise & hare) en O(1) espacio."}],"ejemplo":[],"qa":[{"q":"¿Qué técnica detecta ciclos en una secuencia funcional con O(1) espacio?","a":"El algoritmo de Floyd (tortuga y liebre)."}]},{"title":"Caminos mínimos: Dijkstra, Bellman-Ford, Floyd-Warshall, A*","que":[{"t":"p","x":"Pesos no negativos y una fuente: Dijkstra con min-heap, O((V+E) log V) (falla con negativos). Pesos negativos o ciclos negativos: Bellman-Ford, O(V·E), con una pasada extra para detectarlos. Todos los pares: Floyd-Warshall, O(V³). Objetivo único con heurística admisible: A*."}],"ejemplo":[{"t":"code","lang":"python","x":"d, u = heappop(pq)\nif d > dist[u]: continue\nfor v, w in adj[u]:\n    if dist[u] + w < dist[v]:\n        dist[v] = dist[u] + w; heappush(pq, (dist[v], v))"}],"qa":[{"q":"¿Qué algoritmo usar con pesos negativos y una fuente?","a":"Bellman-Ford (O(V·E)); Dijkstra falla con pesos negativos."}]},{"title":"Minimum Spanning Tree: Kruskal y Prim","que":[{"t":"p","x":"Conectar todos los nodos de un grafo no dirigido ponderado con coste mínimo (n-1 aristas, sin ciclos). Kruskal: ordenar aristas y unir con Union-Find, O(E log E). Prim: min-heap desde una raíz, O(E log V), mejor en grafos densos."}],"ejemplo":[],"qa":[{"q":"¿Cómo funciona Kruskal?","a":"Ordena las aristas por peso y añade cada una si Union-Find confirma que no cierra ciclo."}]}]},{"title":"Backtracking","concepts":[{"title":"Backtracking: elijo, sigo, deshago","que":[{"t":"p","x":"Construir la solución decisión por decisión: elegir, seguir, DESHACER y probar otra, podando ramas inválidas. Es DFS sobre el árbol de decisiones con \"deshacer\" (`path.pop()`). Pista: \"todas las combinaciones/permutaciones válidas\", N-reinas, sudoku. Complejidad exponencial/factorial inherente (O(n·n!) en permutaciones); la poda mejora la constante, no el orden. Plantilla choose/explore/unchoose. Error nº1: guardar `path` en vez de una copia `path[:]`, porque el `pop` posterior vacía lo guardado."}],"ejemplo":[{"t":"code","lang":"python","x":"used[i] = True; path.append(n)   # elijo\nbt()                             # sigo\nused[i] = False; path.pop()      # deshago"}],"qa":[{"q":"¿Qué distingue a Backtracking de un DFS normal y por qué guardar `path[:]`?","a":"El paso de \"deshacer\" la elección más la poda de ramas inválidas. Se guarda `path[:]` porque `pop()` modifica la misma lista y vaciaría los resultados ya guardados."}]},{"title":"Subsets / Permutations / Combinations (powerset)","que":[{"t":"p","x":"Subconjuntos: cada elemento entra o no (2ⁿ). Iterativo: empezar con `[[]]` y por cada número copiar todo agregándolo; recursivo: backtracking; también con máscaras de bits. Permutaciones (n!) usan una lista `usado`. Combinaciones C(n,k): el orden no cuenta, se pasa un parámetro `inicio` que solo avanza (así no salen [1,2] y [2,1]), con poda si no quedan números suficientes. Con duplicados: ordenar y saltar repetidos (`i>start and a[i]==a[i-1]`)."}],"ejemplo":[{"t":"code","lang":"python","x":"res = [[]]\nfor n in nums:\n    res += [sub + [n] for sub in res]"}],"qa":[{"q":"\"Genera TODOS los subconjuntos\", ¿qué patrón, qué tamaño tiene el resultado y cómo evitas [1,2] y [2,1] en combinaciones?","a":"Subsets; 2^n subconjuntos. En combinaciones, con un parámetro `inicio` que solo avanza."}]},{"title":"Poda: combinación que suma target","que":[{"t":"p","x":"Si lo acumulado pasa del target, esa rama muere (`return`). Si se puede repetir, la llamada sigue desde el mismo índice; ordenando se convierte en `break`."}],"ejemplo":[],"qa":[{"q":"¿Desde qué índice sigue la recursión si se permite repetir?","a":"Desde el mismo índice, no el siguiente."}]},{"title":"Duplicados: saltar el repetido del nivel","que":[{"t":"p","x":"Ordenar y saltar el valor igual al anterior dentro del mismo nivel (no del camino). En permutaciones con duplicados la condición es: igual al `i-1` y el `i-1` NO está usado."}],"ejemplo":[],"qa":[{"q":"¿Por qué \"no usado\" en permutaciones con duplicados?","a":"Si el anterior no está usado ya se volvió de esa rama y repetir el valor genera un clon."}]},{"title":"Paréntesis válidos: restricción dentro de la generación","que":[{"t":"p","x":"Se puede abrir si quedan aperturas; se puede cerrar solo si hay más abiertos que cerrados. Es imposible generar basura, no hace falta validar."}],"ejemplo":[],"qa":[{"q":"¿Cuándo se puede cerrar un paréntesis?","a":"Solo si hay más abiertos que cerrados."}]},{"title":"Letras del teléfono y producto cartesiano","que":[{"t":"p","x":"Cada nivel es un dígito y las ramas sus letras; profundidad fija. Caso vacío devuelve `[]`, no `[\"\"]` (\"ninguna combinación\" vs \"una combinación vacía\")."}],"ejemplo":[],"qa":[{"q":"¿Qué devuelve con string vacío?","a":"`[]`."}]},{"title":"Partición en palíndromos: decidir dónde cortar","que":[{"t":"p","x":"La decisión es \"dónde corto\" (`texto[inicio:fin]`); se poda si el trozo no es palíndromo. El árbol de decisiones puede ser sobre índices o cortes, no solo elementos."}],"ejemplo":[],"qa":[{"q":"¿Cuál es la decisión de cada nivel?","a":"Dónde cortar el string."}]},{"title":"Buscar palabra en tablero (DFS con deshacer)","que":[{"t":"p","x":"DFS sobre grid como en islas, pero desmarcando al volver (la casilla puede servir en otro camino). Truco: pisar la casilla con `#` y restaurarla."}],"ejemplo":[],"qa":[{"q":"¿En qué difiere del DFS de islas?","a":"Debe deshacer la marca de visitado al volver."}]},{"title":"N reinas","que":[{"t":"p","x":"Modelado: una reina por fila, se elige columna. Diagonales identificadas con `fila - col` y `fila + col` en sets junto a columnas ocupadas. reinas(8)=92."}],"ejemplo":[],"qa":[{"q":"¿Cómo identificas una diagonal?","a":"Con `fila - columna` (una dirección) y `fila + columna` (la otra)."}]},{"title":"Restaurar IPs (dos podas)","que":[{"t":"p","x":"Trozos de 1-3 dígitos, rango 0-255, sin ceros a la izquierda (\"0\" vale, \"01\" no). Poda dura por valor y poda por cuántos trozos faltan vs dígitos restantes."}],"ejemplo":[],"qa":[{"q":"¿Qué trozos de IP se descartan?","a":"Los mayores que 255 o con cero a la izquierda."}]}]},{"title":"Heaps y greedy","concepts":[{"title":"Top K Elements","que":[{"t":"p","x":"Mantener un heap de tamaño k mientras se recorre: O(n log k), O(k). Para los k MAYORES se usa un MIN-heap de tamaño k (la raíz es el más chico de los mejores; si llega uno mayor, sale la raíz). Para los k menores, max-heap. `heapq` de Python es min-heap; atajo `heapq.nlargest`. Quickselect da el k-ésimo en O(n) promedio."}],"ejemplo":[{"t":"code","lang":"python","x":"heap = []\nfor n in nums:\n    heapq.heappush(heap, n)\n    if len(heap) > k: heapq.heappop(heap)"}],"qa":[{"q":"Para los k más grandes, ¿por qué un MIN-heap?","a":"Porque su raíz es el más chico de tus k mejores; si llega uno mayor, sacas la raíz y metes el nuevo. O(n log k)."}]},{"title":"Two Heaps","que":[{"t":"p","x":"Un max-heap con la mitad baja y un min-heap con la mitad alta, balanceados (difieren en <=1); la mediana está en la frontera. Inserción O(log n), consulta O(1). Pista: mediana de un flujo. En Python el max-heap se simula negando valores."}],"ejemplo":[],"qa":[{"q":"Necesitas la mediana de un flujo de números, ¿qué patrón?","a":"Two Heaps: max-heap (mitad baja) y min-heap (mitad alta) balanceados."}]},{"title":"K-way Merge","que":[{"t":"p","x":"Fundir k listas ya ordenadas con un min-heap: se mete el primero de cada lista, se saca el menor y se mete el siguiente de esa lista. O(N log k), espacio O(k). Generaliza el merge de Merge Sort."}],"ejemplo":[],"qa":[{"q":"Tienes k listas ordenadas y quieres fundirlas, ¿qué patrón y complejidad?","a":"K-way Merge con min-heap; O(N log k)."}]},{"title":"Quickselect y Median of Medians","que":[{"t":"p","x":"K-ésimo elemento sin ordenar todo: Quickselect con partición (Lomuto) y pivote aleatorio, O(n) promedio y O(n²) peor; Median of Medians garantiza O(n) determinista con constante alta."}],"ejemplo":[],"qa":[{"q":"¿Complejidad de Quickselect?","a":"O(n) promedio, O(n²) en el peor caso."}]},{"title":"Greedy","que":[{"t":"p","x":"En cada paso tomas lo mejor localmente sin reconsiderar, normalmente tras ordenar por el criterio correcto (en intervalos, por fin). O(n log n). Riesgo: no siempre es correcto; si una elección local puede arruinar el global, es DP. Ejemplos: Jump Game, Gas Station, Task Scheduler, Huffman."}],"ejemplo":[{"t":"code","lang":"python","x":"intervals.sort(key=lambda x: x[1])   # por FIN\ncount, end = 0, float('-inf')\nfor s, e in intervals:\n    if s >= end: count += 1; end = e"}],"qa":[{"q":"¿Qué distingue Greedy de Dynamic Programming?","a":"Greedy toma el óptimo local y nunca reconsidera; DP explora subproblemas y recuerda resultados."}]},{"title":"Greedy + Priority Queue","que":[{"t":"p","x":"Combinar greedy con heap: fusionar k listas, Task Scheduler (por frecuencias: `(max_f-1)*(n+1)+max_count`), Reorganize String, Minimum Cost to Connect Sticks (tipo Huffman). O(n log k)."}],"ejemplo":[],"qa":[{"q":"¿Qué problemas combinan greedy con priority queue?","a":"Merge k listas, Task Scheduler, Reorganize String, IPO, Connect Sticks."}]}]},{"title":"Programación dinámica","concepts":[{"title":"Dynamic Programming (marco general)","que":[{"t":"p","x":"Resolver cada subproblema una sola vez y guardar el resultado. Pista: mínimo/máximo/número de formas, subestructura óptima y subproblemas solapados (la recursión pura repite, p. ej. Fibonacci O(2ⁿ)). Top-down (memoización) o bottom-up (tabulación). Marco de 6 pasos: estado, definir `dp[estado]`, transición, casos base, orden de iteración, extraer respuesta."}],"ejemplo":[{"t":"code","lang":"python","x":"dp = [0] + [float('inf')] * amount\nfor x in range(1, amount + 1):\n    for c in coins:\n        if c <= x: dp[x] = min(dp[x], dp[x - c] + 1)"}],"qa":[{"q":"¿Cuáles son los pasos para plantear una DP?","a":"Estado, definir dp[estado], transición, casos base, orden de iteración y extraer la respuesta."}]},{"title":"DP lineal 1D y DP 2D (grid)","que":[{"t":"p","x":"1D: cada estado depende de unos pocos anteriores (Climbing Stairs, House Robber, Decode Ways); optimizable a O(1). 2D/grid: estado `(fila, col)` (Unique Paths, Min Path Sum), O(m·n) y arreglo rodante O(n); Dungeon Game se llena al revés."}],"ejemplo":[],"qa":[{"q":"¿A qué se optimiza el espacio de una DP 1D tipo Fibonacci?","a":"A O(1) con dos variables."}]},{"title":"DP Mochila (Knapsack)","que":[{"t":"p","x":"Ítems con peso/valor y capacidad: O(n·W) con arreglo 1D. Iterar la capacidad al revés = 0/1 (cada ítem una vez); al derecho = ilimitada (Coin Change). Casos: Subset Sum, Partition Equal Subset Sum, Target Sum."}],"ejemplo":[{"t":"code","lang":"python","x":"for i in range(n):\n    for w in range(W, weight[i]-1, -1):   # al revés = 0/1\n        dp[w] = max(dp[w], dp[w - weight[i]] + value[i])"}],"qa":[{"q":"¿Qué cambia entre mochila 0/1 e ilimitada?","a":"El sentido de iterar la capacidad: al revés (0/1) o al derecho (ilimitada)."}]},{"title":"DP de cadenas, LIS/LCS","que":[{"t":"p","x":"String DP con estado `(i, j)` sobre prefijos: LCS (coincidencia = diagonal +1, si no max de arriba/izquierda), Edit Distance (1 + min de reemplazar/borrar/insertar), O(m·n). LIS: O(n²) con DP o O(n log n) con patience sorting (arreglo `tails` y búsqueda binaria)."}],"ejemplo":[],"qa":[{"q":"¿Cómo se mejora LIS a O(n log n)?","a":"Con un arreglo `tails` y búsqueda binaria (patience sorting)."}]},{"title":"DP de intervalos, de dígitos y con bitmask; tree DP y state machine","que":[{"t":"p","x":"Interval DP (Matrix Chain, Burst Balloons): estado `[i,j]`, iterar por longitud, O(n³). Digit DP: contar enteros en [L,R] con propiedad sobre dígitos (`tight`, `pos`), `f(R)-f(L-1)`. Bitmask DP: n<=20, subconjuntos, `dp[mask]`, O(2ⁿ·n) (TSP). Tree DP: post-order fusionando hijos. State Machine: estados finitos por paso (Best Time to Buy and Sell Stock)."}],"ejemplo":[],"qa":[{"q":"¿Cuándo usar Bitmask DP?","a":"Cuando el conjunto es pequeño (n<=20-22) y se rastrean subconjuntos o asignaciones (TSP, emparejamientos)."}]}]},{"title":"Estructuras y técnicas avanzadas","concepts":[{"title":"Trie (árbol de prefijos)","que":[{"t":"p","x":"Árbol donde cada nodo es una letra y cada camino desde la raíz deletrea un prefijo; cada nodo tiene un dict de hijos y bandera `is_word`. Búsqueda O(L), independiente de cuántas palabras hay. Pista: prefijos, autocompletar, diccionario, Word Search II. Un hash set solo responde palabras exactas. Variantes: comodín `.` con DFS y trie binario para XOR máximo."}],"ejemplo":[{"t":"code","lang":"python","x":"class Trie:\n    def __init__(self): self.children = {}; self.is_word = False\n    def insert(self, word):\n        node = self\n        for ch in word:\n            node = node.children.setdefault(ch, Trie())\n        node.is_word = True"}],"qa":[{"q":"Prefijos de strings o autocompletar, ¿qué patrón?","a":"Trie: búsqueda O(largo de palabra), sin importar cuántas palabras haya."}]},{"title":"Bit Manipulation","que":[{"t":"p","x":"Operar sobre bits (AND, OR, XOR, shifts) para resolver en O(1) espacio. Pista: \"aparece una sola vez / pares menos uno\", contar bits, máscaras. XOR: `a^a=0`, `a^0=a`. `n & (n-1)` apaga el bit 1 más bajo (contar bits, potencia de 2 si da 0); `n & -n` lo aísla; `1<<i` prende el bit i; `n & 1` mira si es impar. Idiomas: get/set/clear/toggle bit."}],"ejemplo":[{"t":"code","lang":"python","x":"x = 0\nfor n in nums: x ^= n    # queda el único sin pareja"}],"qa":[{"q":"\"Todos aparecen dos veces menos uno\", ¿qué patrón y por qué funciona?","a":"Bit Manipulation con XOR: los pares se cancelan (`a^a=0`) y queda el único."}]},{"title":"Segment Tree y Fenwick Tree (BIT)","que":[{"t":"p","x":"Consultas por rango con actualizaciones puntuales: ambos construyen en O(n) y consultan/actualizan en O(log n). Fenwick usa `i += i & -i` / `i -= i & -i`, menos memoria; Segment Tree es más flexible (min/max/GCD) y con lazy propagation soporta actualización de rango."}],"ejemplo":[],"qa":[{"q":"¿Qué usar para suma de rango con actualizaciones?","a":"Fenwick Tree o Segment Tree (O(log n) por operación)."}]},{"title":"Sparse Table (RMQ)","que":[{"t":"p","x":"Para arreglos estáticos y operación idempotente (min, max, GCD): preproceso O(n log n), consulta O(1) con dos rangos solapados. No válida para suma/XOR."}],"ejemplo":[],"qa":[{"q":"¿Por qué la Sparse Table exige operación idempotente?","a":"Porque la consulta usa dos rangos solapados, que solo es correcto si repetir un elemento no cambia el resultado."}]},{"title":"Mo's Algorithm y Sqrt Decomposition","que":[{"t":"p","x":"Mo: consultas de rango offline ordenadas por bloques de √n, extender/contraer con add/remove en O(1), O((n+q)√n). Sqrt Decomposition: bloques de tamaño √n con consulta/actualización O(√n), alternativa simple a Segment Tree."}],"ejemplo":[],"qa":[{"q":"¿Complejidad de Mo's Algorithm?","a":"O((n+q)·√n)."}]},{"title":"Reservoir Sampling","que":[{"t":"p","x":"Muestreo uniforme de k elementos de un stream de longitud desconocida en una pasada y O(k) memoria: para `i>=k`, `j=randint(0,i)` y si `j<k` reemplazar. Cada elemento queda con probabilidad k/n."}],"ejemplo":[],"qa":[{"q":"¿Cuándo se usa Reservoir Sampling?","a":"Para muestrear uniformemente de un stream de tamaño desconocido en una sola pasada."}]},{"title":"Algoritmos de strings: KMP, Rabin-Karp, Z, Manacher","que":[{"t":"p","x":"Búsqueda de patrón en tiempo lineal. KMP: arreglo de fallos `pi` (borde propio más largo), O(n+m). Rabin-Karp: rolling hash, O(n+m) esperado. Z-function sobre `pat+'#'+text`. Manacher: todos los palíndromos en O(n) transformando a `#a#b#`."}],"ejemplo":[],"qa":[{"q":"¿Qué algoritmo halla todos los palíndromos en O(n)?","a":"Manacher."}]},{"title":"Teoría de números para algoritmos","que":[{"t":"p","x":"Criba de Eratóstenes O(n log log n); GCD de Euclides O(log); potencia modular rápida O(log n); binomiales modulares con factoriales e inversos (Fermat); trial division O(√n)."}],"ejemplo":[],"qa":[{"q":"¿Cómo calcular `a^e mod M` rápido?","a":"Con exponenciación binaria (fast power) en O(log e)."}]},{"title":"Meet in the Middle","que":[{"t":"p","x":"Cuando n≈30-45 (2ⁿ es demasiado, 2^(n/2) manejable): dividir en dos mitades, generar sub-sumas, ordenar una y combinar con búsqueda binaria. O(2^(n/2)·n)."}],"ejemplo":[],"qa":[{"q":"¿Cuándo aplicar Meet in the Middle?","a":"Cuando 2ⁿ es inviable pero 2^(n/2) sí (n≈30-45), p. ej. subset sum exacto."}]},{"title":"Heavy-Light Decomposition y LCA","que":[{"t":"p","x":"Consultas sobre caminos en árboles: HLD (cadenas pesadas + segment tree, O(log² n)); LCA por binary lifting (consulta O(log n)) o Euler tour + sparse table (O(1)). Raro en LeetCode, común en Codeforces."}],"ejemplo":[],"qa":[{"q":"¿Para qué sirve HLD?","a":"Para consultas y actualizaciones sobre caminos de un árbol, descomponiéndolo en cadenas pesadas."}]},{"title":"Geometría computacional","que":[{"t":"p","x":"Producto cruz para orientación (>0 izquierda, <0 derecha, 0 colineal), convex hull (Andrew, O(n log n)), área de polígono (shoelace), closest pair O(n log n)."}],"ejemplo":[],"qa":[{"q":"¿Qué indica el signo del producto cruz de tres puntos?","a":"La orientación: positivo giro a la izquierda, negativo a la derecha, cero colineales."}]}]},{"title":"Estudio","concepts":[{"title":"Roadmap Tracker (estado de estudio)","que":[{"t":"p","x":"Lista basada en roadmap.sh (Python y DSA): básicos, estructuras (heaps, BST, recursión), OOP, decoradores, iteradores, regex, gestores de paquetes, typing, formatters, file handling. Pendientes: queues, hash tables, complejidad, BFS/DFS, Trie, Union-Find."}],"ejemplo":[],"qa":[{"q":"¿Qué temas de DSA siguen pendientes en el tracker?","a":"Queues, hash tables, complejidad algorítmica, BFS/DFS, Trie y Disjoint Set."}]}]}]});
